#[tokio::test]
#[ignore="explicit exact76b real Bank same-nonce recovery competition"]
async fn actual_same_nonce_explicit_sync_recovery_is_mutually_exclusive_in_both_orders(){
 let mut rows=Vec::new();
 for cancel_first in[false,true]{
  let(mut f,_,_)=genuine_fixture().await;let nkey=at_actor(f.program,f.boot);let initial=account(&f.context,nkey).await;let n=u64at(&initial.data,120);let treasury=at(f.program,b"treasury");let before_book=account(&f.context,treasury).await;let before_mint=account(&f.context,at(f.program,b"lab-mint")).await;let before_reserve=account(&f.context,at(f.program,b"lab-reserve")).await;
  let mut suffix=f.book();suffix.push(rw(at(f.program,b"mining")));let original=f.native(1101,1,2,100_000_000u64.to_le_bytes().to_vec(),suffix.clone()).await;let cancel=f.native(1101,1,2,99_999_999u64.to_le_bytes().to_vec(),suffix).await;
  assert_ne!(original.data,cancel.data);assert_eq!(&original.data[112..144],&cancel.data[112..144]);let original_hash=biolab_economy::typed_hash(4,&[&original.data]);let cancel_hash=biolab_economy::typed_hash(4,&[&cancel.data]);assert_ne!(original_hash,cancel_hash);
  let(winning,losing,win_hash,lose_hash)=if cancel_first{(&cancel,&original,cancel_hash,original_hash)}else{(&original,&cancel,original_hash,cancel_hash)};
  let(cu,_)=f.send(&[winning.clone()],true).await;let actual=account(&f.context,nkey).await;assert_eq!(u64at(&actual.data,120),n+1);assert_eq!(&actual.data[128..160],&win_hash);assert_ne!(&actual.data[128..160],&lose_hash);let(_,failure)=f.send(&[losing.clone()],false).await;assert!(failure.contains("InstructionError(0"),"{failure}");assert_eq!(account(&f.context,nkey).await,actual);same_value(account(&f.context,treasury).await,&before_book);same_value(account(&f.context,at(f.program,b"lab-mint")).await,&before_mint);same_value(account(&f.context,at(f.program,b"lab-reserve")).await,&before_reserve);
  rows.push(json!({"order":if cancel_first{"explicitCancelFirst"}else{"originalFirst"},"nonce":n,"finalNonce":n+1,"winnerRequestSHA256":hex(&win_hash),"loserRequestSHA256":hex(&lose_hash),"nativeCacheMatchesWinner":true,"loserRejectedAtInstructionZero":true,"originalBusinessSuccessInferredFromCancel":false,"balanceAndSupplyUnchanged":true,"runtimeRentEpochFirstLoadNormalizationExcluded":true,"successCU":cu,"failedTransactionSignatureFeeStillCharged":true}));drop(f.input);assert!(f.signer.wait().unwrap().success());
 }
 let report=json!({"schema":"BIO-BANK-EXPLICIT-RECOVERY-COMPETITION-1","fixtureOnly":true,"productionAdmission":false,"networkBroadcast":false,"cold":false,"elfSHA256":ELF_SHA,"checkpointSHA256":CHECKPOINT_SHA,"scope":"two independent copies of exact genuinely earned BIO ledger; both contenders are existing SYNC_EMISSIONS with identical actor/opId/nonce and different signed maxRent payload/H4; no cancel opcode/fee/asset patch","actualSignedV1BankTransactions":4,"sameActorSameNonceDistinctFrames":true,"atMostOneNativeExecutionInEitherOrder":true,"branches":rows});let file=root().join("programs/transaction-transport/evidence/recovery-competition-bank-76b35cfb.json");assert!(!file.exists());fs::write(&file,serde_json::to_vec_pretty(&report).unwrap()).unwrap();println!("BANK_RECOVERY_COMPETITION_PASS {report}");
}
